 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdbool.h>
#include <nuttx/debug.h>

#include <sys/param.h>

#include <nuttx/board.h>

#include "chip.h"
#include "arm_internal.h"
#include "stm32_gpio.h"
#include "nucleo-n657x0-q.h"

#include <arch/board/board.h>

#ifdef CONFIG_ARCH_LEDS

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Indexed by BOARD_LED_<color> */

static const uint32_t g_ledmap[BOARD_NLEDS] =
{
  GPIO_LD5,
  GPIO_LD6,
  GPIO_LD7,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void phy_set_led(int led, bool state)
{
  /* Active Low */

  stm32_gpiowrite(g_ledmap[led], !state);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: board_autoled_initialize
 ****************************************************************************/

void board_autoled_initialize(void)
{
  int i;

  /* Configure the LD5, LD6, and LD7 GPIOs for output. Initial state is OFF */

  for (i = 0; i < nitems(g_ledmap); i++)
    {
      stm32_configgpio(g_ledmap[i]);
      stm32_gpiowrite(g_ledmap[i], true);
    }
}

/****************************************************************************
 * Name: board_autoled_on
 ****************************************************************************/

void board_autoled_on(int led)
{
  switch (led)
    {
    case LED_HEAPALLOCATE:
      phy_set_led(BOARD_LED_GREEN, false);
      phy_set_led(BOARD_LED_BLUE,  false);
      phy_set_led(BOARD_LED_RED,   false);
      break;

    case LED_IDLE:
      phy_set_led(BOARD_LED_GREEN, true);
      phy_set_led(BOARD_LED_BLUE,  false);
      phy_set_led(BOARD_LED_RED,   false);
     break;

    case LED_IRQSENABLED:
      phy_set_led(BOARD_LED_GREEN, false);
      phy_set_led(BOARD_LED_BLUE,  true);
      phy_set_led(BOARD_LED_RED,   false);
      break;

    case LED_STACKCREATED:
      phy_set_led(BOARD_LED_GREEN, true);
      phy_set_led(BOARD_LED_BLUE,  true);
      phy_set_led(BOARD_LED_RED,   false);
     break;

    case LED_INIRQ:
      phy_set_led(BOARD_LED_GREEN, false);
      phy_set_led(BOARD_LED_BLUE,  false);
      phy_set_led(BOARD_LED_RED,   true);
      break;

    case LED_SIGNAL:
      phy_set_led(BOARD_LED_GREEN, true);
      phy_set_led(BOARD_LED_BLUE,  false);
      phy_set_led(BOARD_LED_RED,   true);
      break;

    case LED_ASSERTION:
      phy_set_led(BOARD_LED_GREEN, false);
      phy_set_led(BOARD_LED_BLUE,  true);
      phy_set_led(BOARD_LED_RED,   true);
      break;

    case LED_PANIC:
      phy_set_led(BOARD_LED_GREEN, true);
      phy_set_led(BOARD_LED_BLUE,  true);
      phy_set_led(BOARD_LED_RED,   true);
      break;

    default:
      break;
    }
}

/****************************************************************************
 * Name: board_autoled_off
 ****************************************************************************/

void board_autoled_off(int led)
{
  switch (led)
    {
    case LED_SIGNAL:
      phy_set_led(BOARD_LED_RED,   false);
      phy_set_led(BOARD_LED_GREEN, false);
      break;

    case LED_INIRQ:
      phy_set_led(BOARD_LED_RED,   false);
      break;

    case LED_ASSERTION:
      phy_set_led(BOARD_LED_BLUE,  false);
      break;

    case LED_PANIC:
      phy_set_led(BOARD_LED_GREEN, false);
      phy_set_led(BOARD_LED_RED,   false);
      phy_set_led(BOARD_LED_BLUE,  false);
      break;

    case LED_IDLE:
      phy_set_led(BOARD_LED_GREEN, false);
      break;

    default:
      break;
    }
}

#endif /* CONFIG_ARCH_LEDS */

/****************************************************************************
 * boards/arm/stm32n6/nucleo-n657x0-q/src/stm32_userleds.c
