    if (!(RCC->SR & RCC_SR_PLL4RDY)) {
        RCC->PLL4CFGR1 = (2U << RCC_PLL4CFGR1_PLL4SEL_Pos)
            | (3U << RCC_PLL4CFGR1_PLL4DIVM_Pos)
            | (25U << RCC_PLL4CFGR1_PLL4DIVN_Pos);
        RCC->PLL4CFGR2 = 0;
        RCC->PLL4CFGR3 = (1U << RCC_PLL4CFGR3_PLL4PDIV1_Pos)
            | (1U << RCC_PLL4CFGR3_PLL4PDIV2_Pos)
