         | (STM32_PLL1_M << RCC_PLL1CFGR1_DIVM_SHIFT)
         | (STM32_PLL1_N << RCC_PLL1CFGR1_DIVN_SHIFT);
  putreg32(regval, STM32_RCC_PLL1CFGR1);

