         | ((STM32_PLL1_IC1_DIV - 1) << RCC_ICCFGR_INT_SHIFT),
           STM32_RCC_IC1CFGR);
  putreg32(RCC_ICCFGR_SEL_PLL1
         | ((STM32_PLL1_IC1_DIV * 2 - 1) << RCC_ICCFGR_INT_SHIFT),
           STM32_RCC_IC2CFGR);
  putreg32(RCC_ICCFGR_SEL_PLL1
         | ((STM32_PLL1_IC1_DIV * 4 - 1) << RCC_ICCFGR_INT_SHIFT),
           STM32_RCC_IC3CFGR);
  putreg32(RCC_ICCFGR_SEL_PLL1
         | ((STM32_PLL1_IC1_DIV * 3 - 1) << RCC_ICCFGR_INT_SHIFT),
           STM32_RCC_IC6CFGR);
  putreg32(RCC_ICCFGR_SEL_PLL1
         | ((STM32_PLL1_IC1_DIV * 2 - 1) << RCC_ICCFGR_INT_SHIFT),
           STM32_RCC_IC11CFGR);

